## Code Example
```javascript
// Minimal Kleene 3-valued helpers
const val = {T:2, U:1, F:0};
function not(x){ return x==='T'?'F': x==='F'?'T':'U'; }
function land(a,b){
  const table = {T:{T:'T',U:'U',F:'F'}, U:{T:'U',U:'U',F:'F'}, F:{T:'F',U:'F',F:'F'}};
  return table[a][b];
}
function lor(a,b){
  const table = {T:{T:'T',U:'T',F:'T'}, U:{T:'T',U:'U',F:'U'}, F:{T:'T',U:'U',F:'F'}};
  return table[a][b];
}
function imp(a,b){ return lor(not(a), b); }
function equiv(a,b){ return land(imp(a,b), imp(b,a)); }
```

